import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import {VMS_URL} from "../Config/Config";


export default function EditPass ({passObj}) {

    const [sessionUserData, setsessionUserData] = useState([]);
    const [viewLoading, setViewLoading] = useState(false);
    const [editLoading, setEditLoading] = useState(false);
    const [viewData, setViewData] = useState([]);
    const [editData, setEditData] = useState({
        "orgid": sessionUserData.OrgId,
        "userid": 1,
        "Operation": "EDIT",
        "RequestPass": {
            "RequestId": "",
            "VisitorName": "",
            "Email": "",
            "Mobile": "",
            "CompanyName": "",
            "RequestDate": "",
            "MeetingDate": "",
            "IsVehicle": true,
            "VehicleInfo": "",
            "ReturnOfMaterials": "",
            "Remarks": "",
            "NoOfMembers": "",
            "VisitorType": "",
            "Status": "",
            "IsActive": 1
        },
        "Attendees": []
      });

      useEffect(() => {
        setEditData({"orgid": sessionUserData.OrgId,
            "userid": sessionUserData.UserId,
            "Operation": "EDIT",
            "RequestPass": {
                "RequestId": passObj?.RequestId,
                "VisitorName": passObj?.VisitorName,
                "Email": passObj?.Email,
                "Mobile": passObj?.Mobile,
                "CompanyName": passObj?.CompanyName,
                "RequestDate": passObj?.RequestDate,
                'MeetingDate': passObj?.MeetingDate ? passObj.MeetingDate.split('T')[0] : "",
                "IsVehicle": true,
                "VehicleInfo": passObj?.VehicleInfo,
                "ReturnOfMaterials": passObj?.ReturnOfMaterials,
                "Remarks": passObj?.Remarks,
                "NoOfMembers": passObj?.NoOfMembers,
                "VisitorType": passObj?.VisitorType,
                "Status": passObj?.Status,
                "IsActive": passObj?.IsActive
            },
            "Attendees": []}
        );
      }, [passObj]);
      

    useEffect(() => {
        const userDataString = sessionStorage.getItem('userData');
        if (userDataString) {
            const userData = JSON.parse(userDataString);
            setsessionUserData(userData);
        } else {
            console.log('User data not found in sessionStorage');
        }
    }, []);

    const fetchViewEditData = async () => {
        setViewLoading(true);
        try {
            const response = await fetch(`${VMS_URL}getReqPassById?RequestId=${passObj.RequestId}`);
            if (response.ok) {
                const data = await response.json();
                if (data.Status) {
                    setViewData(data.ResultData);
                    console.log(data.ResultData, 'edit data......')
                    console.log(passObj, 'passobj getting from list...');
                } else {
                    setViewData([]);
                }
            } else {
                console.error('Failed to fetch attendees data:', response.statusText);
            }
        } catch (error) {
            console.error('Error fetching attendees data:', error.message);
        } finally {
            setViewLoading(false);
        }
    };

    useEffect(() => {
        fetchViewEditData();
    }, [passObj.RequestId]);

    // const handleChange = (e) => {
    //     const { name, value } = e.target;
    //     setEditData((prevData) => ({
    //         ...prevData,
    //         RequestPass: {
    //             ...prevData.RequestPass,
    //             [name]: value,
    //         },
    //     }));
    // };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setEditData((prevData) => ({
            ...prevData,
            RequestPass: {
                ...prevData.RequestPass,
                [name]: value, // This key must match the input's name attribute
            },
        }));
    };
    

    const handleAttendeeChange = (index, key, value) => {
        setEditData((prevData) => {
            const updatedAttendees = [...prevData.Attendees];
            updatedAttendees[index][key] = value;
            return { ...prevData, Attendees: updatedAttendees };
        });
    };

    const handleSubmit = async () => {
        try {
            editData.userid = sessionUserData.Id;
            console.log(editData, 'data sending to api')
            setEditLoading(true);
            const response = await fetch(`${VMS_URL}ManageRequestPass`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify(editData),
            });

            if (response.ok) {
                setEditLoading(false);
                const result = await response.json();
                console.log("Edit successful:", result);
                window.location.reload();
            } else {
                setEditLoading(false);
                console.error("Edit failed:", response.statusText);
            }
        } catch (error) {
            setEditLoading(false);
            console.error("Error submitting data:", error.message);
        }
    };
      

    return (
        <div className="offcanvas offcanvas-end" tabIndex="-1" id="offcanvasRightEdit" aria-labelledby="offcanvasRightLabel"
            style={{ width: '85%' }}
        >
             <style>
                {`
                    @media (min-width: 768px) { /* Medium devices and up (md) */
                        #offcanvasRightAdd {
                            width: 45% !important;
                        }
                    }
                `}
            </style>
            <div className="offcanvas-header d-flex justify-content-between align-items-center">
               <h5 id="offcanvasRightLabel" className="mb-0">Edit Visit</h5>
               <div className="d-flex align-items-center">
                   <button 
                       className="btn btn-primary me-2"
                       type="button"
                       onClick={handleSubmit}
                   >
                       {editLoading ? 'Updating...' : 'Update'}
                   </button>
                   <button 
                       type="button" 
                       className="btn-close" 
                       data-bs-dismiss="offcanvas" 
                       aria-label="Close"
                   ></button>
               </div>
           </div>
            {viewLoading ? <p className="text-center">Loading...</p> :
                <div className="offcanvas-body" style={{ marginTop: '-2rem' }}>
                    <div className="row">
                        <div className="col-6 mb-2">
                            <label className="form-label justify-content-start d-flex">Date</label>
                            <input 
                                type="date"
                                className="form-control"
                                name="MeetingDate" 
                                value={editData.RequestPass.MeetingDate}
                                onChange={handleChange}
                            />
                        </div>
                        <div className="col-6 mb-2">
                            <label className="form-label justify-content-start d-flex">Attendee Name</label>
                            <input 
                                type="text"
                                className="form-control"
                                placeholder="Attendee name"
                                name="VisitorName" 
                                value={editData.RequestPass.VisitorName}
                                onChange={handleChange}
                            />
                        </div>
                        <div className="col-6 mb-2">
                            <label className="form-label justify-content-start d-flex">Mobile No</label>
                            <input 
                                type="number"
                                className="form-control"
                                placeholder="Mobile number"
                                name="Mobile" 
                                value={editData.RequestPass.Mobile}
                                onChange={handleChange}
                            />
                        </div>
                        <div className="col-6 mb-2">
                            <label className="form-label justify-content-start d-flex">Email Id</label>
                            <input 
                                type="email"
                                name="Email"
                                className="form-control"
                                placeholder="Enter Email address"
                                value={editData.RequestPass.Email}
                                onChange={handleChange}
                            />
                        </div>
                        <div className="col-6 mb-2">
                            <label className="form-label justify-content-start d-flex">Vehicle No</label>
                            <input 
                                type="text"
                                className="form-control"
                                placeholder="Vehicle number"
                                name="VehicleInfo" 
                                value={editData.RequestPass.VehicleInfo}
                                onChange={handleChange}
                            />
                        </div>
                        <div className="col-6 mb-2">
                        <label className="form-label justify-content-start d-flex">Visitor Type<span className="text-danger fw-bold">*</span></label>
                        <select 
                            className="form-select"
                            name="VisitorType" 
                            value={editData.RequestPass.VisitorType}
                            onChange={handleChange}
                        >
                            <option>Choose visitor type</option>
                            <option value='1'>Supplier</option>
                            <option value='2'>Customer</option>
                        </select>
                    </div>
                        <div className="col-12 mb-2">
                            <label className="form-label justify-content-start d-flex">Remarks</label>
                            <textarea 
                                name="Remarks"
                                className="form-control" 
                                rows={3} 
                                placeholder="Notes.."
                                value={editData.RequestPass.Remarks}
                                onChange={handleChange}
                            ></textarea>
                        </div>
                    </div>
                    <h4 className={`text-start my-2 ${viewData?.visitors?.length > 0 ? 'd-block' : 'd-none'}`}>Attndees:</h4>
                    {viewData?.map((attendee, index) => (
                        <div key={index} className="row mb-2 align-items-center">
                            <div className="col-4">
                                <label>Name</label>
                            <input
                                type="text"
                                className="form-control"
                                value={attendee.AttendeName || ""}
                                onChange={(e) => handleAttendeeChange(index, "AttendeName", e.target.value)}
                            />
                            </div>
                            <div className="col-4">
                                <label>Phone</label>
                            <input
                                type="number"
                                className="form-control"
                                value={attendee.PhoneNumber || ""}
                                onChange={(e) => handleAttendeeChange(index, "PhoneNumber", e.target.value)}
                            />
                            </div>
                            <div className="col-4">
                                <label>Email</label>
                            <input
                                type="email"
                                className="form-control"
                                value={attendee.Email || ""}
                                onChange={(e) => handleAttendeeChange(index, "Email", e.target.value)}
                            />
                            </div>
                        </div>
                    ))}
                </div>
            }
        </div>
    )
};

EditPass.propTypes = {
    passObj: PropTypes.object.isRequired
};