import React, { useEffect, useState } from "react";
import Swal from 'sweetalert2';
import { VMS_URL } from "../Config/Config";
import PropTypes from "prop-types";

export default function EditUser({ editObj }) {

  const [sessionUserData, setsessionUserData] = useState({});
  const [rolesData, setRolesData] = useState([]);
  const [editSubmitLoading, setEditSubmitLoading] = useState(false);

  const [formData, setFormData] = useState({
    Id: '',
    RoleId: "",
    Name: "",
    Password: "",
    IsActive: true,
    CreatedBy: "",
    OrgId: "",
    Mobile: "",
    Email: "",
    IsMobile: false,
    Gender: "",
    UpdatedBy: sessionUserData.Id,
  });

  // Fetch session user data
  useEffect(() => {
    const userDataString = sessionStorage.getItem("userData");
    if (userDataString) {
      const userData = JSON.parse(userDataString);
      setsessionUserData(userData);
      setFormData((prev) => ({
        ...prev,
        CreatedBy: userData.Id,
        OrgId: userData.OrgId,
        UpdatedBy: userData.Id
      }));
    }
  }, []);

  // Fetch roles data
  const fetchRolesData = async () => {
    try {
      const response = await fetch(`${VMS_URL}getRoles?OrgId=${sessionUserData.OrgId}`);
      if (response.ok) {
        const data = await response.json();
        setRolesData(data.ResultData);
        console.log(data.ResultData)
      } else {
        console.error("Failed to fetch roles:", response.statusText);
      }
    } catch (error) {
      console.error("Error fetching roles:", error.message);
    }
  };

  useEffect(() => {
    fetchRolesData();
  }, [editObj]);

  useEffect(() => {
    if (editObj) {
      setFormData({
        Id: editObj.Id,
        RoleId: editObj.RoleId || "",
        Name: editObj.Name || "",
        Password: editObj.Password || "",
        IsActive: editObj.IsActive ? 1 : 0,
        CreatedBy: editObj.CreatedBy || "",
        OrgId: editObj.OrgId || "",
        Mobile: editObj.Mobile || "",
        Email: editObj.Email || "",
        IsMobile: editObj.IsMobile ? 1 : 0,
        Gender: editObj.Gender ? 1 : 0,
        UpdatedBy: sessionUserData.Id,
      });
    }
  }, [editObj, sessionUserData.Id]);  

  // Handle form input changes
  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevState) => ({
      ...prevState,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setEditSubmitLoading(true);

    try {
        if (formData.IsMobile) {
            formData.IsMobile = 1;
        }
        if (!formData.IsMobile) {
            formData.IsMobile = 0;
        }
      const response = await fetch(`${VMS_URL}UPDTUsers`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      console.log(formData);

      if (response.ok) {
        const data = await response.json();
        console.log(data);
        if (data.ResultData[0].Status === "Success") {
          Swal.fire({
            title: "Success",
            text: "User has been updated successfully.",
            icon: "success",
          }).then(() => window.location.reload());
        } else {
          Swal.fire({
            title: "Error",
            text: data?.ResultData[0]?.Message || "Failed to update user.",
            icon: "error",
          });
        }
      } else {
        console.error("Failed to submit form:", response.statusText);
        Swal.fire({
          title: "Error",
          text: "Failed to submit form.",
          icon: "error",
        });
      }
    } catch (error) {
      console.error("Error during submission:", error.message);
      Swal.fire({
        title: "Error",
        text: "An unexpected error occurred.",
        icon: "error",
      });
    } finally {
      setEditSubmitLoading(false);
    }
  };


  return (
    <div
      className="offcanvas offcanvas-end"
      tabIndex="-1"
      id="offcanvasRightEdit"
      aria-labelledby="offcanvasRightLabel"
      style={{ minWidth: "45%", maxWidth: "45%" }}
    >
      <form onSubmit={handleSubmit}>
        <div className="offcanvas-header d-flex justify-content-between align-items-center">
          <h5 id="offcanvasRightLabel" className="mb-0">Edit User</h5>
          <div className="d-flex align-items-center">
            <button className="btn btn-primary me-2" type="submit" disabled={editSubmitLoading}>
              {editSubmitLoading ? "Submitting..." : "Submit"}
            </button>
            <button
              type="button"
              className="btn-close"
              data-bs-dismiss="offcanvas"
              aria-label="Close"
            ></button>
          </div>
        </div>
        <div className="offcanvas-body" style={{ marginTop: "-2rem", maxHeight: "42rem", overflowY: "auto" }}>
          <div className="row">
            <div className="col-6 mb-2">
              <label className="form-label">Name<span className="text-danger">*</span></label>
              <input
                type="text"
                name="Name"
                className="form-control"
                placeholder="Enter user name"
                value={formData.Name}
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">Password<span className="text-danger">*</span></label>
              <input
                type="password"
                name="Password"
                className="form-control"
                placeholder="Enter password"
                value={formData.Password}
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">Role<span className="text-danger">*</span></label>
              <select
                className="form-select"
                name="RoleId"
                value={formData.RoleId}
                onChange={handleInputChange}
                // required
              >
                <option value="">Select Role</option>
                {rolesData && rolesData.map((role) => (
                  <option key={role.Id} value={role.Id}>
                    {role.Name}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">Mobile<span className="text-danger">*</span></label>
              <input
                type="text"
                name="Mobile"
                className="form-control"
                placeholder="Enter mobile number"
                value={formData.Mobile}
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">Email<span className="text-danger">*</span></label>
              <input
                type="email"
                name="Email"
                className="form-control"
                placeholder="Enter email address"
                value={formData.Email}
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">Gender<span className="text-danger">*</span></label>
              <select
                className="form-select"
                name="Gender"
                value={formData.Gender}
                onChange={handleInputChange}
                required
              >
                <option value="">Select Gender</option>
                <option value="1">Male</option>
                <option value="0">Female</option>
              </select>
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">Is Mobile</label>
              <input
                type="checkbox"
                name="IsMobile"
                className="ms-2"
                checked={formData.IsMobile}
                onChange={handleInputChange}
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">Active</label>
              <input
                type="checkbox"
                name="IsActive"
                className="ms-2"
                checked={formData.IsActive}
                onChange={handleInputChange}
              />
            </div>
          </div>
        </div>
      </form>
    </div>
  );
}

EditUser.propTypes = {
  editObj: PropTypes.object.isRequired,
};
