import React, { useEffect, useState } from "react";
import Swal from "sweetalert2";
import PropTypes from "prop-types";
import { VMS_URL_CONTRACTOR } from "../Config/Config";

export default function EditContactor({ editObj }) {
//   console.log(editObj);

  const [sessionUserData, setSessionUserData] = useState([]);
  const [shiftsData, setShiftsData] = useState([]);
  const [addSubmitLoading, setAddSubmitLoading] = useState(false);

  const [formData, setFormData] = useState({
    ContractorName: "",
    ShiftTypeId: "",
    Passes: "",
    ValidStartDt: "",
    ValidEndDt: "",
    UpdatedBy: "",
    OrgId: "",
    Id: "",
  });

  useEffect(() => {
    const userDataString = sessionStorage.getItem("userData");
    if (userDataString) {
      const userData = JSON.parse(userDataString);
      setSessionUserData(userData);
    } else {
      console.log("User data not found in sessionStorage");
    }
  }, []);

  useEffect(() => {
    if (editObj) {
      setFormData({
        ContractorName: editObj.ContractorName || "",
        ShiftTypeId: editObj.ShiftTypeId || "",
        Passes: editObj.RequiredPasses || "",
        ValidStartDt: editObj.ValidStartDt ? editObj.ValidStartDt.split("T")[0] : "",
        ValidEndDt: editObj.ValidEndDt ? editObj.ValidEndDt.split("T")[0] : "",
        UpdatedBy: sessionUserData.UserId || "",
        OrgId: editObj.OrgId || "",
        Id: editObj.Id || "",
      });
    }
  }, [editObj, sessionUserData]);
  

  const fetchShiftsData = async () => {
    try {
      const response = await fetch(
        `${VMS_URL_CONTRACTOR}getShiftTimings?OrgId=${sessionUserData.OrgId}`
      );
      if (response.ok) {
        const data = await response.json();
        setShiftsData(data.ResultData);
      } else {
        console.error("Failed to fetch shifts data:", response.statusText);
      }
    } catch (error) {
      console.error("Error fetching shifts data:", error.message);
    }
  };

  useEffect(() => {
    if (sessionUserData.OrgId) {
      fetchShiftsData();
    }
  }, [sessionUserData]);

  const handleContactorChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevState) => ({
      ...prevState,
      [name]: value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      setAddSubmitLoading(true);

      const payload = {
        ContractorName: formData.ContractorName,
        ShiftTypeId: formData.ShiftTypeId,
        RequiredPasses : formData.Passes,
        ValidStartDt: formData.ValidStartDt,
        ValidEndDt: formData.ValidEndDt,
        UpdatedBy: sessionUserData.UserId,
        OrgId: sessionUserData.OrgId,
        Id: formData.Id,
        UpdatedBy: sessionUserData.Id,
      };
      console.log(payload);

      const response = await fetch(
        `${VMS_URL_CONTRACTOR}UPDTContractors`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(payload),
        }
      );

      if (response.ok) {
        const data = await response.json();
        setAddSubmitLoading(false);
        console.log(data.ResultData);

        if (data.ResultData[0].Status === "Success") {
          Swal.fire({
            title: "Success",
            text: "The contractor details have been updated successfully.",
            icon: "success",
          }).then(() => {
            window.location.reload();
          });
        } else {
          Swal.fire({
            title: "Error",
            text: data?.Message || "Failed to update the contractor.",
            icon: "error",
          });
        }
      } else {
        Swal.fire({
          title: "Error",
          text: "Failed to submit the request.",
          icon: "error",
        });
      }
    } catch (error) {
      console.error("Error during submission:", error.message);
      Swal.fire({
        title: "Error",
        text: "An unexpected error occurred.",
        icon: "error",
      });
    } finally {
      setAddSubmitLoading(false);
    }
  };

  return (
    <div
      className="offcanvas offcanvas-end"
      tabIndex="-1"
      id="offcanvasRightEdit"
      aria-labelledby="offcanvasRightLabel"
      style={{ minWidth: "45%", maxWidth: "45%" }}
    >
      <form onSubmit={handleSubmit}>
        <div className="offcanvas-header d-flex justify-content-between align-items-center">
          <h5 id="offcanvasRightLabel" className="mb-0">
            Edit Contractor
          </h5>
          <div className="d-flex align-items-center">
            <button
              className="btn btn-primary me-2"
              type="submit"
              disabled={addSubmitLoading}
            >
              {addSubmitLoading ? "Updating..." : "Update"}
            </button>
            <button
              type="button"
              className="btn-close"
              data-bs-dismiss="offcanvas"
              aria-label="Close"
            ></button>
          </div>
        </div>
        <div
          className="offcanvas-body"
          style={{
            marginTop: "-2rem",
            maxHeight: "42rem",
            overflowY: "auto",
          }}
        >
          <div className="row">
            <div className="col-6 mb-2">
              <label className="form-label">
                Name<span className="text-danger">*</span>
              </label>
              <input
                type="text"
                name="ContractorName"
                className="form-control"
                placeholder="Enter contractor name"
                value={formData.ContractorName}
                onChange={handleContactorChange}
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">
                Shifts<span className="text-danger">*</span>
              </label>
              <select
                className="form-select"
                name="ShiftTypeId"
                value={formData.ShiftTypeId}
                onChange={handleContactorChange}
              >
                <option value="">Choose Shift</option>
                {shiftsData.map((item, index) => (
                  <option key={index} value={item.Id}>
                    {item.ShiftName}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">
                Start Date<span className="text-danger">*</span>
              </label>
              <input
                type="date"
                name="ValidStartDt"
                className="form-control"
                value={formData.ValidStartDt}
                onChange={handleContactorChange}
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">
                End Date<span className="text-danger">*</span>
              </label>
              <input
                type="date"
                name="ValidEndDt"
                className="form-control"
                value={formData.ValidEndDt}
                onChange={handleContactorChange}
              />
            </div>
            <div className="col-6 mb-2">
              <label className="form-label">
                Request Passes<span className="text-danger">*</span>
              </label>
              <input
                type="number"
                name="Passes"
                className="form-control"
                placeholder="Enter number of passes"
                value={formData.Passes}
                onChange={handleContactorChange}
              />
            </div>
          </div>
        </div>
      </form>
    </div>
  );
}

EditContactor.propTypes = {
  editObj: PropTypes.object.isRequired,
};
