import React, { useEffect, useState } from "react";
import Swal from 'sweetalert2';
import {VMS_URL} from "../Config/Config";


export default function AddVisit () {

    const [sessionUserData, setsessionUserData] = useState([]);
    const [addSubmitLoading, setAddSubmitLoading] = useState(false);
    const [attendees, setAttendees] = useState([]);

    useEffect(() => {
        const userDataString = sessionStorage.getItem('userData');
        if (userDataString) {
            const userData = JSON.parse(userDataString);
            setsessionUserData(userData);
        } else {
            console.log('User data not found in sessionStorage');
        }
    }, []);

    const [formData, setFormData] = useState({
        orgid: sessionUserData.OrgId,
        userid: sessionUserData.RegId,
        Operation: "ADD",
        RequestPass: {
            VisitorName: "",
            Email: "",
            Mobile: "",
            CompanyName: "",
            RequestDate: "",
            MeetingDate: "",
            IsVehicle: false,
            VehicleInfo: "",
            ReturnOfMaterials: "",
            Remarks: "",
            NoOfMembers: 0,
            VisitorType: "",
            Vehicleinfo: "",
            Status: "DRAFT",
            IsActive: 1,
        },
            Attendees: [],
    });

    const handleRequestPassChange = (e) => {
        const { name, value } = e.target;
        setFormData((prevState) => ({
            ...prevState,
            RequestPass: {
                ...prevState.RequestPass,
                [name]: value,
            },
        }));
    };
    
    const addAttendee = () => {
        setAttendees([...attendees, { AttendeName: "", PhoneNumber: "", Email: "" }]);
    };
    
    const removeAttendee = (index) => {
        setAttendees(attendees.filter((_, i) => i !== index));
    };

    const [visitorType, setVisitorType] = useState("");

    const handleChange = (event) => {
      setVisitorType(event.target.value);
    };

    const [mobileNumber, setMobileNumber] = useState("");
    const [error, setError] = useState("");

    const handleMobileChange = (e) => {
        const value = e.target.value;
        const regex = /^[0-9]*$/; // Allow only numbers

        if (!regex.test(value)) {
        setError("Only numeric values are allowed.");
        return;
        }

        if (value.length > 10) {
        setError("Mobile number cannot exceed 10 digits.");
        } else if (value.length < 10 && value.length > 0) {
        setError("Mobile number must be exactly 10 digits.");
        } else {
        setError(""); // Clear error when valid
        }

        setMobileNumber(value);
    };


    
    // const handleAttendeeChange = (index, field, value) => {
    //     const updatedAttendees = [...attendees];
    //     updatedAttendees[index][field] = value;
    //     setAttendees(updatedAttendees);
    // };
    const handleAttendeeChange = (index, field, value) => {
        setAttendees((prevAttendees) => {
            const updatedAttendees = [...prevAttendees];
            updatedAttendees[index] = {
                ...updatedAttendees[index],
                [field]: value,
            };
            return updatedAttendees;
        });
    };

    const getCurrentDateAndTime = () => {
        const now = new Date();
    
        const day = String(now.getDate()).padStart(2, '0');
        const month = String(now.getMonth() + 1).padStart(2, '0');
        const year = now.getFullYear();
    
        const hours = String(now.getHours()).padStart(2, '0');
        const minutes = String(now.getMinutes()).padStart(2, '0');
        const seconds = String(now.getSeconds()).padStart(2, '0');
    
        const formattedDate = `${year}-${month}-${day}`;
        const formattedTime = `${hours}:${minutes}:${seconds}`;
    
        return { formattedDate, formattedTime };
    };
    
    const { formattedDate, formattedTime } = getCurrentDateAndTime();

    // const handleSubmit = async (e) => {
    //     e.preventDefault();
    //     try {

           
    //         console.log(attendees)
    
    //         const updatedFormData = { 
    //             ...formData, 
    //             Attendees: attendees 
    //         };

    //         setAddSubmitLoading(true);
    //         if (sessionUserData) {
    //             formData.userid = sessionUserData.Id;
    //             formData.orgid = sessionUserData.OrgId;
    //             formData.CreatedBy = sessionUserData.Id;
    //         }
    //         formData.RequestPass.NoOfMembers = attendees.length;
    //         formData.RequestPass.VisitorType = visitorType;
    //         formData.RequestPass.Mobile = mobileNumber;
    //         formData.RequestPass.RequestDate = formattedDate;
    //         console.log(updatedFormData, 'data sending to api');


    //         const response = await fetch(`${VMS_URL}ManageRequestPass`, {
    //             method: 'POST',
    //             headers: {
    //                 'Content-Type': 'application/json',
    //             },
    //             body: JSON.stringify(updatedFormData),
    //         });
            
    //         if (response.ok) {
    //             const data = await response.json();
    //             // console.log('Request data', data);
    //             setAddSubmitLoading(false);
    
    //             if (data[0].Success == 1) {
    //                 Swal.fire({
    //                     title: 'Success',
    //                     text: 'The record has been added successfully.',
    //                     icon: 'success',
    //                 }).then(() => {
    //                     // window.location.reload();
    //                 });
    //             } else {
    //                 Swal.fire({
    //                     title: 'Error',
    //                     text: 'There was an error adding the record.',
    //                     icon: 'error',
    //                 });
    //                 setAddSubmitLoading(false);
    //             }
    //         } else {
    //             console.error('Request failed', response);
    //             Swal.fire({
    //                 title: 'Error',
    //                 text: 'Failed to submit request',
    //                 icon: 'error',
    //             });
    //             setAddSubmitLoading(false);
    //         }
    //     } catch (error) {
    //         console.error('Error:', error);
    //         Swal.fire({
    //             title: 'Error',
    //             text: 'An error occurred',
    //             icon: 'error',
    //         });
    //         setAddSubmitLoading(false);
    //     }
    // };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const cleanedAttendees = attendees.map(({ AttendeName, PhoneNumber, Email }) => ({
                AttendeName: AttendeName || "",
                PhoneNumber: PhoneNumber || "",
                Email: Email || "",
                Remarks: "",
            }));
    
            const updatedFormData = { 
                ...formData, 
                Attendees: cleanedAttendees,
                RequestPass: {
                    ...formData.RequestPass,
                    VisitorType: visitorType,
                    Mobile: mobileNumber,
                },
            };
    
            setAddSubmitLoading(true);
            updatedFormData.userid = sessionUserData.Id;
            updatedFormData.orgid = sessionUserData.OrgId;
            updatedFormData.CreatedBy = sessionUserData.Id;
            updatedFormData.RequestPass.NoOfMembers = attendees.length + 1;
            updatedFormData.RequestPass.RequestDate = formattedDate;
    
            console.log(updatedFormData, 'data sending to API');
    
            const response = await fetch(`${VMS_URL}ManageRequestPass`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(updatedFormData),
            });
    
            if (response.ok) {
                const data = await response.json();
                setAddSubmitLoading(false);
                console.log(data)
    
                if (data[0].Success == 1) {
                    Swal.fire({
                        title: 'Success',
                        text: 'The record has been added successfully.',
                        icon: 'success',
                    }).then(() => {
                        // window.location.reload();
                    });
                } else {
                    Swal.fire({
                        title: 'Error',
                        text: 'There was an error adding the record.',
                        icon: 'error',
                    });
                    setAddSubmitLoading(false);
                }
            } else {
                console.error('Request failed', response);
                Swal.fire({
                    title: 'Error',
                    text: 'Failed to submit request',
                    icon: 'error',
                });
                setAddSubmitLoading(false);
            }
        } catch (error) {
            console.error('Error:', error);
            Swal.fire({
                title: 'Error',
                text: 'An error occurred',
                icon: 'error',
            });
            setAddSubmitLoading(false);
        }
    };
    


    return (
        <div className="offcanvas offcanvas-end" tabIndex="-1" id="offcanvasRightAdd" aria-labelledby="offcanvasRightLabel"
            style={{
                width: '85%',
            }}
        >
            <style>
                {`
                    @media (min-width: 768px) { /* Medium devices and up (md) */
                        #offcanvasRightAdd {
                            width: 45% !important;
                        }
                    }
                `}
            </style>
        <form onSubmit={handleSubmit}>
            <div className="offcanvas-header d-flex justify-content-between align-items-center">
               
                <h5 id="offcanvasRightLabel" className="mb-0">Create Visit</h5>
                <div className="d-flex align-items-center">
                    <button 
                        className="btn btn-primary me-2"
                        type="submit"
                    >
                        {addSubmitLoading ? 'Submitting...' : 'Submit'}
                    </button>
                    <button 
                        type="button" 
                        className="btn-close" 
                        data-bs-dismiss="offcanvas" 
                        aria-label="Close"
                    ></button>
                </div>
            </div>
            <div className="offcanvas-body" style={{ marginTop: '-2rem', maxHeight: '42rem', overflowY: 'auto' }}>
                <div className="row">
                    <div className="col-6 mb-2">
                        <label className="form-label justify-content-start d-flex">Date<span className="text-danger fw-bold">*</span></label>
                        <input 
                            type="date"
                            name="MeetingDate"
                            className="form-control"
                            onChange={handleRequestPassChange}
                            required
                        />
                    </div>
                    <div className="col-6 mb-2">
                        <label className="form-label justify-content-start d-flex">Attendee Name<span className="text-danger fw-bold">*</span></label>
                        <input 
                            type="text"
                            name="VisitorName"
                            className="form-control"
                            placeholder="Enter Attendee name"
                            onChange={handleRequestPassChange}
                            required
                        />
                    </div>
                    <div className="col-6 mb-2">
                        <label className="form-label justify-content-start d-flex">Mobile No<span className="text-danger fw-bold">*</span></label>
                        <input 
                            type="number"
                            name="Mobile"
                            className="form-control"
                            placeholder="Enter Mobile number"
                            value={mobileNumber}
                            onChange={handleMobileChange}
                            onWheel={(e) => e.target.blur()}
                        />
                        {error && <span className="text-danger">{error}</span>}
                    </div>
                    <div className="col-6 mb-2">
                        <label className="form-label justify-content-start d-flex">Email Id<span className="text-danger fw-bold">*</span></label>
                        <input 
                            type="email"
                            name="Email"
                            className="form-control"
                            placeholder="Enter Email address"
                            onChange={handleRequestPassChange}
                            required
                        />
                    </div>
                    <div className="col-6 mb-2">
                        <label className="form-label justify-content-start d-flex">Visitor Type<span className="text-danger fw-bold">*</span></label>
                        <select 
                            className="form-select"
                            value={visitorType}
                            onChange={handleChange}
                        >
                            <option>Choose visitor type</option>
                            <option value='1'>Supplier</option>
                            <option value='2'>Customer</option>
                        </select>
                    </div>
                    <div className="col-6 mb-2">
                        <label className="form-label justify-content-start d-flex">Vehicle No<span className="text-danger fw-bold">*</span></label>
                        <input 
                            type="text"
                            name="Vehicleinfo"
                            className="form-control"
                            placeholder="Enter vehicle number"
                            onChange={handleRequestPassChange}
                            required
                        />
                    </div>
                    <div className="col-12 mb-2">
                        <label className="form-label justify-content-start d-flex">Remarks</label>
                        <textarea 
                            name="Remarks"
                            className="form-control" 
                            rows={3} 
                            placeholder="Enter notes.."
                            onChange={handleRequestPassChange}
                        ></textarea>
                    </div>
                    <div className="d-flex mt-2">
                        <h6 className="text-start mt-1">Attendee List:</h6>
                        <button className="btn btn-info d-flex ms-auto text-hover-primary" type="button" onClick={addAttendee}>
                            <i className="fa-solid fa-person-circle-plus fs-3"></i>
                        </button>
                    </div>
                    {attendees.map((attendee, index) => (
                        <div key={index} className="row mb-2 align-items-center">
                            <div className="col-4">
                                <label className="form-label justify-content-start d-flex">
                                    Name <span className="text-danger fw-bold">*</span>
                                </label>
                                <input
                                    type="text"
                                    className="form-control"
                                    value={attendee.AttendeName}
                                    onChange={(e) => handleAttendeeChange(index, 'AttendeName', e.target.value)}
                                    placeholder="Attendee name"
                                />
                            </div>
                            <div className="col-3">
                                <label className="form-label justify-content-start d-flex">
                                    Mobile <span className="text-danger fw-bold">*</span>
                                </label>
                                <input
                                    type="number"
                                    className="form-control"
                                    value={attendee.PhoneNumber}
                                    onChange={(e) => handleAttendeeChange(index, 'PhoneNumber', e.target.value)}
                                    onWheel={(e) => e.target.blur()}
                                    placeholder="Mobile no"
                                />
                            </div>
                            <div className="col-4">
                                <label className="form-label justify-content-start d-flex">
                                    Email <span className="text-danger fw-bold">*</span>
                                </label>
                                <input
                                    type="email"
                                    className="form-control"
                                    value={attendee.Email}
                                    onChange={(e) => handleAttendeeChange(index, 'Email', e.target.value)}
                                    placeholder="Email id"
                                />
                            </div>
                            <div 
                                className="col-1 d-flex justify-content-end btn text-hover-warning" 
                                style={{ marginTop: '2rem', cursor: 'pointer' }}
                                onClick={() => removeAttendee(index)}
                            >
                                <i className="fa-regular fa-trash-can fs-4 text-danger"></i>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </form>
    </div>
    )
}