import React, {useState, useEffect} from "react";
import Base from "../Config/Base";
import { useParams } from "react-router-dom";
import { VMS_URL_CONTRACTOR, VMS_URL_REPORT } from "../Config/Config";


export default function ReportData () {

    const { ReportId } = useParams();
    const [sessionUserData, setsessionUserData] = useState({});
    const [error, setError] = useState([]);
    const [loading, setLoading] = useState([]);
    const [report, setReport] = useState("");
    const [shiftsData, setShiftsData] = useState([]);
    const [selectedShiftId, setSelectedShiftId] = useState(null);

    useEffect(() => {
        const userDataString = sessionStorage.getItem("userData");
        if (userDataString) {
            const userData = JSON.parse(userDataString);
            setsessionUserData(userData);
        }
    }, []);

    const fetchShiftsData = async () => {
      try {
          const response = await fetch(`${VMS_URL_CONTRACTOR}getShiftTimings?OrgId=${sessionUserData.OrgId}`);
          if (response.ok) {
              const data = await response.json();
              setShiftsData(data.ResultData);
          } else {
              console.error('Failed to fetch shifts data:', response.statusText);
          }
      } catch (error) {
          console.error('Error fetching shifts data:', error.message);
      } 
  };

  useEffect(() => {
      if (sessionUserData.OrgId) {
          fetchShiftsData();
      }
  }, [sessionUserData]);

    const today = new Date();

    const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);

    const formatDate = (date) => {
      return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
    };

    const [selectedFromDt, setSelectedFromDt] = useState(formatDate(startOfMonth));
    const [selectedEndDt, setSelectedEndDt] = useState(formatDate(today));

  const fetchReport = async (e) => {
    
    setLoading(true);
    setError(null);

    const payload ={
        "OrgId": sessionUserData.OrgId,
        "UserId": sessionUserData.Id,
        "ReportId": ReportId,
        "ReportCriteria": {
          "FromDate": selectedFromDt,
          "ToDate": selectedEndDt,
          "ShiftTypeId": 0
        },
    }
    console.log(payload)

    try {
      const response = await fetch(`${VMS_URL_REPORT}getreport`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        throw new Error("Failed to fetch the report");
      }

      const data = await response.json();
      setReport(data);
      console.log(data)
    } catch (error) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };
    
  const { data, headers } = report;
          

    return (
        <Base>
          <div id="kt_app_content" className="app-content flex-column-fluid">
            <div id="kt_app_content_container" className="app-container container-xxl">
                <div className="row gy-10 gx-xl-10"></div>
                  <form>
                    <div className="row">
                        <div className="col-3">
                          <label className="form-label">From Date</label>
                          <input
                            type="date"
                            className="form-control"
                            value={selectedFromDt}
                            onChange={(e) => setSelectedFromDt(e.target.value)}
                          />
                        </div>
                        <div className="col-3">
                          <label className="form-label">To Date</label>
                          <input
                            type="date"
                            className="form-control"
                            value={selectedEndDt}
                            onChange={(e) => setSelectedEndDt(e.target.value)}
                          />
                        </div>
                        <div className="col-3">
                          <label className="form-label">To Date</label>
                          <select
                                className="form-select"
                                name="ShiftTypeId"
                                value={selectedShiftId}
                                onChange={(e) => setSelectedShiftId(e.target.value)}
                            >
                                <option value="">Choose Shift</option>
                                {shiftsData.map((item, index) => (
                                    <option key={index} value={item.Id}>
                                        {item.ShiftName}
                                    </option>
                                ))}
                            </select>
                        </div>
                        <div className="col-2">
                          <button className="btn btn-primary mt-5" type="button" onClick={fetchReport}>Submit</button>
                        </div>
                    </div>
                  </form>
                  <div className="card mt-5">
                    <div className="table-responsive">
                      <table className="table align-middle table-row-dashed fs-6 gy-5">
                          <thead>
                              <tr className="text-start text-gray-500 fw-bold fs-7 text-uppercase gs-0">
                                  {/* Dynamically rendering headers */}
                                  {headers && headers.map((header, index) => (
                                      <th key={index} style={{ padding: "8px", textAlign: "center" }}>
                                          {header.trim()}
                                      </th>
                                  ))}
                              </tr>
                          </thead>
                          <tbody className="fw-semibold text-gray-600">
                              {data && data.map((row, rowIndex) => (
                                  <tr key={rowIndex}>
                                      {headers.map((header, colIndex) => (
                                          <td key={colIndex} style={{ padding: "8px", textAlign: "center" }}>
                                              {row[header.trim()] || "N/A"} {/* Fallback to "N/A" if no data */}
                                          </td>
                                      ))}
                                  </tr>
                              ))}
                          </tbody>
                      </table>
                    </div>
                  </div>
              </div>
          </div>
        </Base>
    )
}