import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { VMS_URL } from "../Config/Config";
import LogoImg from "../Assests/Images/logo.jpg";

export default function SignIn() {
  const [showPassword, setShowPassword] = useState(false);

  const [userName, setUserName] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);

  const navigate = useNavigate();

  const togglePasswordVisibility = () => {
    setShowPassword((prevState) => !prevState);
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError(null);
    setLoading(false);
    setErrorMessage(null);

    try {
      setLoading(true);

      const url = `${VMS_URL}SignIn?UserName=${encodeURIComponent(
        userName
      )}&Password=${encodeURIComponent(password)}`;
      console.log(url);

      const response = await fetch(url, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      });

      const result = await response.json();
      console.log(result, "rrrrr");
      setLoading(false);

      if (response.ok) {
        if (result.Status) {
          setLoading(false);
          sessionStorage.setItem(
            "userData",
            JSON.stringify(result["ResultData"][0])
          );
          navigate("/dashboard");
        } else {
          setLoading(false);
          setErrorMessage(result.error);
          console.error("Error during sign-in", result.error);
          setError(result.error);
        }
      } else {
        setLoading(false);
        setErrorMessage(result.error);
        console.error("Error during sign-in", result.error);
        setError(result.error);
      }
    } catch (err) {
      setErrorMessage("Something went wrong. Please try again later.");
      setLoading(false);
      setError("Something went wrong. Please try again later.");
    }
  };

  const [formData, setFormData] = useState({
    Name: "",
    NewPassword: "",
    ConfirmPassword: "",
  });

  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const toggleShowNewPassword = () => setShowNewPassword(!showNewPassword);
  const toggleShowConfirmPassword = () =>
    setShowConfirmPassword(!showConfirmPassword);

  const handleFPWSubmit = async (e) => {
    e.preventDefault();
    if (formData.NewPassword !== formData.ConfirmPassword) {
      alert("Passwords do not match!");
      return;
    }

    try {
      const response = await fetch(`${VMS_URL}forgotPassword`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          Name: formData.Name,
          Password: formData.NewPassword,
        }),
      });

      if (response.ok) {
        alert("Password updated successfully!");
        setFormData({ Name: "", NewPassword: "", ConfirmPassword: "" });
      } else {
        alert("Failed to update password. Please try again.");
      }
    } catch (error) {
      console.error("Error:", error);
      alert("An error occurred. Please try again later.");
    }
  };

  return (
    <div className="d-flex flex-column flex-root" id="kt_app_root">
      <div className="d-flex flex-column flex-lg-row flex-column-fluid">
        <div className="d-flex flex-column flex-lg-row-fluid w-lg-50 p-10 order-2 order-lg-1">
          <div className="d-flex flex-center flex-column flex-lg-row-fluid">
            <img src={LogoImg} style={{ height: "10rem" }} />
            <div className="w-lg-500px p-10 mt-5">
              <form className="form w-100" onSubmit={handleSubmit}>
                <div className="text-center mb-11">
                  <h1 className="text-gray-900 fw-bolder mb-3">Sign In</h1>
                </div>
                <div className="fv-row mb-8">
                  <label className="form-label">
                    <i className="fa-regular fa-user me-2"></i>User Name
                  </label>
                  <input
                    type="text"
                    placeholder="Enter User Name"
                    name="username"
                    autoComplete="off"
                    className="form-control bg-transparent"
                    value={userName}
                    onChange={(e) => setUserName(e.target.value)}
                    required
                    disabled={loading} // Disable field when loading is true
                  />
                </div>
                <div className="fv-row mb-3 position-relative">
                  <label className="form-label">
                    <i className="fa-solid fa-key me-2"></i>Password
                  </label>
                  <input
                    type={showPassword ? "text" : "password"}
                    placeholder="Enter Password"
                    name="password"
                    autoComplete="off"
                    className="form-control bg-transparent"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    disabled={loading} // Disable field when loading is true
                  />
                  <span
                    onClick={loading ? null : togglePasswordVisibility} // Disable toggle when loading
                    style={{
                      position: "absolute",
                      top: "70%",
                      right: "10px",
                      transform: "translateY(-50%)",
                      cursor: loading ? "not-allowed" : "pointer", // Change cursor style
                    }}
                  >
                    <i
                      className={`fa-regular fa-eye${
                        showPassword ? "-slash" : ""
                      }`}
                    ></i>
                  </span>
                </div>
                {/* Error Message */}
                {errorMessage && (
                  <p className="alert alert-danger">{errorMessage}</p>
                )}
                <div className="d-grid mb-10">
                  <button
                    type="submit"
                    id="kt_sign_in_submit"
                    className="btn btn-primary"
                    disabled={loading}
                  >
                    <span className="indicator-label">
                      {loading ? "Please wait..." : "Sign In"}
                    </span>
                  </button>
                </div>

                <div className="d-flex flex-stack flex-wrap gap-3 fs-base fw-semibold mb-8">
                  <div></div>
                  <a
                    className="link-primary"
                    data-bs-toggle="offcanvas"
                    href="#offcanvasForgotPassword"
                    role="button"
                    aria-controls="offcanvasForgotPassword"
                  >
                    Forgot Password?
                  </a>
                </div>
                <div className="text-gray-500 text-center fw-semibold fs-6">
                  Not a Member yet?
                  <a className="link-primary ms-2">Sign up</a>
                </div>
              </form>
            </div>
          </div>
        </div>
        <div
          className="d-flex flex-lg-row-fluid w-lg-50 bgi-size-cover bgi-position-center order-1 order-lg-2"
          style={{ backgroundImage: "url(assets/media/misc/auth-bg.png)" }}
        >
          <div className="d-flex flex-column flex-center py-7 py-lg-15 px-5 px-md-15 w-100">
            {/* <a href="index.html" className="mb-0 mb-lg-12">
							<img alt="Logo" src="assets/media/logos/custom-1.png" className="h-60px h-lg-75px" />
						</a> */}
            {/* <img className="d-none d-lg-block mx-auto w-275px w-md-50 w-xl-500px mb-10 mb-lg-20" src="assets/media/misc/auth-screens.png" alt="" /> */}
            <h1 className="d-none d-lg-block text-white fs-2qx fw-bolder text-center mb-7">
              Fast, Efficient and Productive
            </h1>
            <div className="d-none d-lg-block text-white fs-base text-center">
              In this kind of post,
              <a
                href="#"
                className="opacity-75-hover text-warning fw-bold me-1"
              >
                the blogger
              </a>
              introduces a person they’ve interviewed
              <br />
              and provides some background information about
              <a
                href="#"
                className="opacity-75-hover text-warning fw-bold me-1"
              >
                the interviewee
              </a>
              and their
              <br />
              work following this is a transcript of the interview.
            </div>
          </div>
        </div>
      </div>

      <div
        className="offcanvas offcanvas-end"
        tabIndex="-1"
        id="offcanvasForgotPassword"
        aria-labelledby="offcanvasForgotPasswordLabel"
      >
        <div className="offcanvas-header">
          <h5 className="offcanvas-title" id="offcanvasForgotPasswordLabel">
            Forgot Password
          </h5>
          <button
            type="button"
            className="btn-close"
            data-bs-dismiss="offcanvas"
            aria-label="Close"
          ></button>
        </div>
        <div className="offcanvas-body">
          <form onSubmit={handleFPWSubmit}>
            <div className="mb-3">
              <label htmlFor="username" className="form-label">
                Username
              </label>
              <input
                type="text"
                id="username"
                name="Name"
                value={formData.Name}
                className="form-control"
                onChange={handleInputChange}
                required
              />
            </div>
            <div className="mb-3">
              <label htmlFor="newPassword" className="form-label">
                New Password
              </label>
              <div className="input-group">
                <input
                  type={showNewPassword ? "text" : "password"}
                  id="newPassword"
                  name="NewPassword"
                  value={formData.NewPassword}
                  className="form-control"
                  autoComplete="off"
                  autoCorrect="off"
                  spellCheck="false"
                  onChange={handleInputChange}
                  required
                />
                <span className="input-group-text">
                  <i
                    className={`fa ${
                      showNewPassword ? "fa-eye" : "fa-eye-slash"
                    }`}
                    style={{ cursor: "pointer" }}
                    onClick={toggleShowNewPassword}
                  ></i>
                </span>
              </div>
            </div>

            <div className="mb-3">
              <label htmlFor="confirmPassword" className="form-label">
                Confirm Password
              </label>
              <div className="input-group">
                <input
                  type={showConfirmPassword ? "text" : "password"}
                  id="confirmPassword"
                  name="ConfirmPassword"
                  value={formData.ConfirmPassword}
                  className="form-control"
                  onChange={handleInputChange}
                  autoComplete="off"
                  autoCorrect="off"
                  spellCheck="false"
                  required
                />
                <span className="input-group-text">
                  <i
                    className={`fa ${
                      showConfirmPassword ? "fa-eye" : "fa-eye-slash"
                    }`}
                    style={{ cursor: "pointer" }}
                    onClick={toggleShowConfirmPassword}
                  ></i>
                </span>
              </div>
            </div>
            <button type="submit" className="btn btn-primary w-100">
              Submit
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
