import React, {useState, useEffect} from 'react';
// import Base from '../Config/Base';
import { VMS_URL } from '../Config/Config';
import RoleSideImg from './rolemenu.jpg';
import Base1 from '../Config/Base1';

export default function RoleMenu () {

    const [sessionUserData, setsessionUserData] = useState({});
    const [rolesData, setRolesData] = useState([]);
    const [menuData, setMenuData] = useState([]);
    const [selectedRole, setSelectedRole] = useState("");
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        const userDataString = sessionStorage.getItem("userData");
        if (userDataString) {
            const userData = JSON.parse(userDataString);
            setsessionUserData(userData);
        }
    }, []);

    const fetchRolesData = async () => {
        if (sessionUserData.OrgId) {
            try {
                const response = await fetch(`${VMS_URL}getRoles?OrgId=${sessionUserData.OrgId}`);
                if (response.ok) {
                    const data = await response.json();
                    setRolesData(data.ResultData);
                } else {
                    console.error('Failed to fetch attendance data:', response.statusText);
                }
            } catch (error) {
                console.error('Error fetching attendance data:', error.message);
            }
        }
    };

    const fetchUserPermissons = async () => {
        if (sessionUserData.OrgId) {
            try {
                setIsLoading(true);
                const response = await fetch(`${VMS_URL}UserPermissions?OrgId=${sessionUserData.OrgId}&RoleId=${selectedRole}&ModuleId=0`);
                if (response.ok) {
                    const data = await response.json();
                    setMenuData(data.ResultData);
                    setIsLoading(false);
                    console.log(data)
                } else {
                    setIsLoading(false);
                    console.error('Failed to fetch attendance data:', response.statusText);
                }
            } catch (error) {
                setIsLoading(false);
                console.error('Error fetching attendance data:', error.message);
            }
        }
    };

    useEffect(() => {
        fetchUserPermissons();
    }, [selectedRole]);

    const handleRoleChange = (e) => {
        setSelectedRole(e.target.value);
        console.log("Selected Role ID:", e.target.value);
    };

    useEffect(() => {
        if (sessionUserData.OrgId) {
            fetchRolesData();
        }
    }, [sessionUserData]);

    const handleCheckboxChange = async (menuId, permissionType, checked) => {
        const updatedMenuData = menuData.map((menu) =>
          menu.AppMenuId === menuId
            ? { ...menu, [permissionType]: checked }
            : menu
        );
        setMenuData(updatedMenuData);
    
        const updatedMenu = updatedMenuData.find((menu) => menu.AppMenuId === menuId);
    
        const payload = {
          orgid: sessionUserData.OrgId,
          RoleId: Number(selectedRole),
          MenuId: menuId,
          IsChecked: updatedMenu.Read ? 1 : 0,
          CanWrite: updatedMenu.Write ? 1 : 0,
          CanDelete: updatedMenu.Delete ? 1 : 0,
          CanExport: updatedMenu.Export ? 1 : 0,
          IsActive: updatedMenu.IsActive ? 1 : 0,
          UpdatedBy: sessionUserData.Id,
        };
        console.log(payload, 'data sending to api');
    
        try {
          const response = await fetch(`${VMS_URL}UpdateUserMenu`, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify(payload),
          });
    
          const result = await response.json();
          if (!response.ok) {
            console.error("Failed to update permissions:", result);
          } else {
                fetchUserPermissons();
            console.log("Permissions updated successfully:", result);
          }
        } catch (error) {
          console.error("Error while updating permissions:", error);
        }
    };

    return (
        <Base1>
            <div className="d-flex flex-column flex-column-fluid">
                <div id="kt_app_content" className="app-content flex-column-fluid">
                <div id="kt_app_content_container" className="app-container container-xxl">
                    <div className='row'>
                        <div className="col-md-4 col-lg-4 col-12 mb-2">
                            <label className="form-label">Role<span className="text-danger">*</span></label>
                            <select
                                className="form-select"
                                name="RoleId"
                                onChange={handleRoleChange}
                                value={selectedRole}
                            >
                                <option>Choose Role</option>
                                {rolesData && rolesData.map((role) => (
                                    <option key={role.Id} value={role.Id}>
                                        {role.Name}
                                    </option>
                                ))}
                            </select>
                        </div>
                        {/*
                        <div className="col-md-4 col-lg-4 col-12 mb-2">
                            <label className="form-label">Module<span className="text-danger">*</span></label>
                            <select
                                className="form-select"
                                name="RoleId"
                            >
                                <option selected disabled>Choose Module</option>
                                {rolesData && rolesData.map((role) => (
                                    <option key={role.Id} value={role.Id}>
                                        {role.Name}
                                    </option>
                                ))}
                            </select>
                        </div>
                        */}
                    </div>
                    <div className="row d-flex align-items-center">
                        <div className="col-md-7 col-12">
                            <div className="table-responsive">
                            <table className="table">
                                <thead>
                                <tr>
                                    <th>#</th>
                                    <th>Menu</th>
                                    <th>Read</th>
                                    <th>Write</th>
                                    <th>Delete</th>
                                    <th>Export</th>
                                    <th>Active</th>
                                </tr>
                                </thead>
                                <tbody>
                                    {isLoading ? (
                                        <tr>
                                            <td colSpan="6" className="text-center">
                                                <div className="container" ></div>
                                            </td>
                                        </tr>
                                    ) : selectedRole ? (
                                        menuData && menuData.length > 0 ? (
                                        menuData.map((menu, index) => (
                                            <tr key={menu.AppMenuId}>
                                                <td>{index + 1}</td>
                                                <td>{menu.MenuName}</td>
                                                <td>
                                                    <div className="form-check form-switch">
                                                    <input
                                                        className="form-check-input"
                                                        type="checkbox"
                                                        role="switch"
                                                        checked={menu.Read}
                                                        onChange={(e) =>
                                                        handleCheckboxChange(menu.AppMenuId, "Read", e.target.checked)
                                                        }
                                                    />
                                                    </div>
                                                </td>
                                                <td>
                                                    <div className="form-check form-switch">
                                                    <input
                                                        className="form-check-input"
                                                        type="checkbox"
                                                        role="switch"
                                                        checked={menu.Write}
                                                        onChange={(e) =>
                                                        handleCheckboxChange(menu.AppMenuId, "Write", e.target.checked)
                                                        }
                                                    />
                                                    </div>
                                                </td>
                                                <td>
                                                    <div className="form-check form-switch">
                                                    <input
                                                        className="form-check-input"
                                                        type="checkbox"
                                                        role="switch"
                                                        checked={menu.Delete}
                                                        onChange={(e) =>
                                                        handleCheckboxChange(menu.AppMenuId, "Delete", e.target.checked)
                                                        }
                                                    />
                                                    </div>
                                                </td>
                                                <td>
                                                    <div className="form-check form-switch">
                                                    <input
                                                        className="form-check-input"
                                                        type="checkbox"
                                                        role="switch"
                                                        checked={menu.Export}
                                                        onChange={(e) =>
                                                        handleCheckboxChange(menu.AppMenuId, "Export", e.target.checked)
                                                        }
                                                    />
                                                    </div>
                                                </td>
                                                <td>
                                                    <div className="form-check form-switch">
                                                    <input
                                                        className="form-check-input"
                                                        type="checkbox"
                                                        role="switch"
                                                        checked={menu.IsActive}
                                                        onChange={(e) =>
                                                        handleCheckboxChange(menu.AppMenuId, "IsActive", e.target.checked)
                                                        }
                                                    />
                                                    </div>
                                                </td>
                                            </tr>
                                        ))
                                        ) : (
                                        <tr>
                                            <td colSpan="6" className="text-center">
                                            No data available for the selected role.
                                            </td>
                                        </tr>
                                        )
                                    ) : (
                                        <tr>
                                        <td colSpan="6" className="text-center">
                                            Please select a role to view the data.
                                        </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                            </div>
                        </div>

                        <div className="col-md-5 col-12 text-center d-none d-md-block d-lg-block">
                            <img
                            src={RoleSideImg}
                            alt="Role Side"
                            className="img-fluid"
                            style={{ maxHeight: "300px", objectFit: "contain" }}
                            />
                        </div>
                    </div>
                    </div>
                </div>
            </div>
        </Base1>
    )
}
